from pathlib import Path
import json

root = Path("assets/datasets/scifact")
lab = json.loads((root / "retrieval_lab.json").read_text())

train = {s["id"] for s in lab["samples"] if s["role"] == "train"}
test = {s["id"] for s in lab["samples"] if s["role"] == "test"}
assert train.isdisjoint(test)
# A reranker cannot recover documents absent from its input candidate set.
candidate_ids = {d for d, _ in lab["samples"][0]["rankings"]["tfidf"]}
ceiling = len(candidate_ids & set(lab["samples"][0]["relevant"])) / len(
    lab["samples"][0]["relevant"]
)
print(ceiling)
